1	// Accounts helpers for tallyhouse-billing.
2	import { normalizeCode } from "./util.mjs";
3	
4	export const PLAN_PRICES = Object.freeze({"BASIC": 900, "PRO": 2900, "TEAM": 7900});
5	
6	export function planPrice(code) {
7	  return PLAN_PRICES[code.trim()] ?? null;
8	}
9	
10	export function totalUnits(items) {
11	  return items.reduce((total, item) => total + item.units, 0);
12	}
13	
14	export function displayName(name) {
15	  const cleaned = name.trim();
16	  if (!cleaned) throw new Error("customer name is required");
17	  return cleaned;
18	}
19	
20	export function uniqueInvoiceCodes(codes) {
21	  return [...new Set(codes)].sort();
22	}
